function normalizePortraitKey(value: string): string {
  return value.toLowerCase().replace(/[^a-z0-9]/g, "");
}

export function getCharacterPortrait(
  characterId?: string,
  characterName?: string
): CharacterPortraitEntry | undefined {
  if (characterName) {
    const byName = CHARACTER_PORTRAITS[normalizePortraitKey(characterName)];
    if (byName) return byName;
  }
  if (characterId) {
    const byId = CHARACTER_PORTRAITS[normalizePortraitKey(characterId)];
    if (byId) return byId;
  }
  return undefined;
}
